const REPO = fileURLToPath(new URL("../", import.meta.url));
const REAL = "research/pi-conformance/1.0.1/lifecycle";
const FAKE = "tests/fixtures/trajectory/fake-pi";

const dirs: string[] = [];
afterAll(() => {
	for (const dir of dirs.splice(0)) rmSync(dir, { recursive: true, force: true });
});

function lines(file: string): EndoEventV0[] {
	return readFileSync(join(REPO, file), "utf8")
		.split("\n")
		.filter(Boolean)
		.map((line) => JSON.parse(line) as EndoEventV0);
}

/** The Pi session id a recording attached to. */
function piSession(events: readonly EndoEventV0[]): string {
	const attached = events.find((event) => event.kind === "harness.attached")!;
	return (attached.payload as { piSessionId: string }).piSessionId;
}

const KEY_A = FAKE_TRAJECTORY_DIGEST_KEYS.a;
const FIXTURE_KEY_FILE = join(REPO, "research", "fixture-keys", "fixture-public.json");

/** Load a committed recording into a scratch durable store and project it through the CLI's read-only path. */
function trajectory(directory: string, name: string, label?: string): EndoTrajectoryV0 {
	const file = `${directory}/${name}.events.jsonl`;
	const events = lines(file);
	const root = mkdtempSync(join(tmpdir(), "endo-trajectory-"));
	dirs.push(root);
	const store = createEndoDurableEventStoreV0(root);
	for (const event of events) store.ingest(event);
	store.close();
	return trajectoryFromStoreV0(root, piSession(events), { label: label ?? file });
}

/** compare(b, a) predicted from compare(a, b): sides swapped, usage and timing deltas negated, digest recomputed. */
function swapped(comparison: EndoTrajectoryComparisonV0): unknown {
	const flip = (value: unknown): unknown => {
		if (value === null || typeof value !== "object") return value;
		if (Array.isArray(value)) return value.map(flip);
		const record = value as Record<string, unknown>;
		const out = Object.fromEntries(Object.entries(record).map(([key, item]) => [key, flip(item)]));
		if ("a" in record && "b" in record) {
			// The entries themselves are swapped whole, not flipped inside.
			out.a = record.b;
			out.b = record.a;
		}
		return out;
	};
	const negate = (value: unknown): unknown => {
		if (typeof value === "number") return value === 0 ? 0 : -value;
		if (value === null || typeof value !== "object") return value;
		return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, negate(item)]));
	};
	const usage = comparison.layers.usage;
	const timing = comparison.layers.timing;
	const body = {
		...comparison,
		a: comparison.b,
		b: comparison.a,
		flags: comparison.flags.map(flip),
		layers: {
			lifecycle: flip(comparison.layers.lifecycle),
			tools: flip(comparison.layers.tools),
			outcome: flip(comparison.layers.outcome),
			usage:
				usage.status === "UNAVAILABLE"
					? flip(usage)
					: {
							status: "DELTAS",
							runs: usage.runs.map((run) => ({
								run: run.run,
								present: { a: run.present.b, b: run.present.a },
								tokens: negate(run.tokens),
							})),
							totals: negate(usage.totals),
						},
			timing:
				timing.status === "UNAVAILABLE"
					? flip(timing)
					: {
							status: "DELTAS",
							clock: "observer",
							runs: timing.runs.map((run) => ({
								run: run.run,
								present: { a: run.present.b, b: run.present.a },
								wallMs: negate(run.wallMs),
							})),
							totals: negate(timing.totals),
						},
		},
		provenance: { a: comparison.provenance.b, b: comparison.provenance.a },
	} as Record<string, unknown>;
	return { ...body, digest: endoRecordDigestV0(body) };
}

/** Compare, and check the result's validity, determinism and symmetry before returning it. */
function compare(a: EndoTrajectoryV0, b: EndoTrajectoryV0): EndoTrajectoryComparisonV0 {
	const result = compareEndoTrajectoriesV0(a, b);
	expect(validateEndoTrajectoryComparisonV0(JSON.parse(JSON.stringify(result)), endoRecordDigestV0)).not.toBeNull();
	expect(canonicalEndoJsonV0(compareEndoTrajectoriesV0(a, b))).toBe(canonicalEndoJsonV0(result));
	expect(canonicalEndoJsonV0(compareEndoTrajectoriesV0(b, a))).toBe(canonicalEndoJsonV0(swapped(result)));
	return result;
}

function expectSelfExact(t: EndoTrajectoryV0): void {
	const result = compare(t, t);
	for (const layer of ["lifecycle", "tools", "outcome"] as const) {
		const length = t.layers[layer].status === "reported" ? t.layers[layer].entries.length : -1;
		expect(result.layers[layer]).toEqual({ status: "EXACT", length });
	}
	expect(result.flags).toEqual([]);
	if (result.layers.usage.status === "DELTAS") {
		for (const run of result.layers.usage.runs) {
			for (const value of Object.values(run.tokens ?? {})) expect(value === null || value === 0).toBe(true);
		}
	}
	if (result.layers.timing.status === "DELTAS") {
		for (const run of result.layers.timing.runs) expect(run.wallMs === null || run.wallMs === 0).toBe(true);
	}
}

describe("the comparison record", () => {
	it("carries its rules verbatim, and the rules say what alignment, usage, flags and symmetry mean", () => {
		const t = trajectory(REAL, "completes");
		expect(compare(t, t).rules).toEqual(ENDO_TRAJECTORY_COMPARISON_RULES_V0);
		expect(ENDO_TRAJECTORY_COMPARISON_RULES_V0.alignment).toMatch(/position .* never by timestamp/);
		expect(ENDO_TRAJECTORY_COMPARISON_RULES_V0.usage).toMatch(/never judged EXACT or DIVERGED/);
		expect(ENDO_TRAJECTORY_COMPARISON_RULES_V0.timing).toMatch(/observer's clock/);
		expect(ENDO_TRAJECTORY_COMPARISON_RULES_V0.equality).toMatch(/one digest domain/);
	});

	it("identity is location-free: the same sessions read from different paths give the same digests", () => {
		const a = trajectory(REAL, "completes", "/one/place");
		const b = trajectory(REAL, "completes", "/somewhere/else");
		expect(a.provenance).toEqual({ store: "/one/place" });
		expect(b.provenance).toEqual({ store: "/somewhere/else" });
		expect(a.digest).toBe(b.digest);
		const x = compare(a, trajectory(REAL, "stop-mid-turn", "/p"));
		const y = compare(b, trajectory(REAL, "stop-mid-turn", "/q"));
		expect(x.digest).toBe(y.digest);
		expect(x.provenance).toEqual({ a: { store: "/one/place" }, b: { store: "/p" } });
		expect(y.provenance).toEqual({ a: { store: "/somewhere/else" }, b: { store: "/q" } });
		// The digest covers the content identities: a side's events digest, session and trajectory digest.
		expect(x.a).toEqual({
			session: a.source.session,
			eventsSha256: a.source.eventsSha256,
			trajectoryDigest: a.digest,
		});
	});

	it("rejects a tampered trajectory or comparison by digest", () => {
		const t = trajectory(REAL, "completes");
		const tampered = JSON.parse(JSON.stringify(t)) as EndoTrajectoryV0;
		(tampered.layers.outcome as { entries: { outcome: string }[] }).entries[0]!.outcome = "failed";
		expect(validateEndoTrajectoryV0(tampered, endoRecordDigestV0)).toBeNull();
		expect(() => compareEndoTrajectoriesV0(t, tampered)).toThrow(/digest/);
		const result = JSON.parse(JSON.stringify(compareEndoTrajectoriesV0(t, t)));
		result.layers.tools = { status: "EXACT", length: 7 };
		expect(validateEndoTrajectoryComparisonV0(result, endoRecordDigestV0)).toBeNull();
	});

	it("never carries raw text: tool arguments only by digest, causes only by reference", () => {
		for (const name of ["baseline", "tool-args-differ"]) {
			const text = canonicalEndoJsonV0(trajectory(FAKE, name));
			for (const raw of ["a.txt", "b.txt", '"ls"', "fake tool result", "fake reply", "hello"])
				expect(text.includes(raw)).toBe(false);
		}
	});
});

describe("REAL Pi 1.0.1 recordings (qwen3.8-27b via llama.cpp)", () => {
	it.each(["completes", "stop-mid-turn", "killed-and-resumed"])(
		"%s against itself is EXACT on every layer",
		(name) => {
			const t = trajectory(REAL, name);
			expect(t.layers.lifecycle.status).toBe("reported");
			expectSelfExact(t);
		},
	);

	it("projection is a pure function of the events: from the file, from the store, and re-parsed", () => {
		const file = `${REAL}/completes.events.jsonl`;
		const events = lines(file);
		const direct = projectPiTrajectoryV0(events, { store: file, session: piSession(events) });
		expect(canonicalEndoJsonV0(trajectory(REAL, "completes"))).toBe(canonicalEndoJsonV0(direct));
		expect(
			canonicalEndoJsonV0(
				projectPiTrajectoryV0(JSON.parse(JSON.stringify(events)), {
					store: file,
					session: `endo.session.pi.${piSession(events)}`,
				}),
			),
		).toBe(canonicalEndoJsonV0(direct));
	});

	it("completes vs stop-mid-turn: identical prefix, first divergence at the STOP, completed vs aborted", () => {
		const result = compare(trajectory(REAL, "completes"), trajectory(REAL, "stop-mid-turn"));
		expect(result.flags).toEqual([]);
		expect(result.layers.lifecycle).toMatchObject({
			status: "DIVERGED",
			index: 3,
			commonPrefix: 3,
			a: { kind: "lifecycle.turn-completed" },
			b: { kind: "lifecycle.stop-requested", facts: { runOpen: true } },
		});
		expect(result.layers.outcome).toMatchObject({
			status: "DIVERGED",
			index: 0,
			a: { outcome: "completed", stopRequested: false },
			b: { outcome: "aborted", stopRequested: true, stopReason: { status: "reported", value: "aborted" } },
		});
		expect(result.layers.tools).toEqual({ status: "EXACT", length: 0 });
		expect(result.layers.usage).toEqual({
			status: "DELTAS",
			runs: [
				{
					run: 1,
					present: { a: true, b: true },
					tokens: {
						input: -1608,
						output: -72,
						cacheRead: 0,
						cacheWrite: 0,
						totalTokens: -1680,
						reasoning: null,
						costTotal: 0,
					},
				},
			],
			totals: {
				tokens: {
					input: -1608,
					output: -72,
					cacheRead: 0,
					cacheWrite: 0,
					totalTokens: -1680,
					reasoning: null,
					costTotal: 0,
				},
			},
		});
		// Wall time is the observer's clock, in its own layer; usage carries only what Pi reported.
		expect(result.layers.timing).toEqual({
			status: "DELTAS",
			clock: "observer",
			runs: [{ run: 1, present: { a: true, b: true }, wallMs: -2743 }],
			totals: { wallMs: -2743 },
		});
		expect(result.digest).toBe("85df2d55f91312e54ad67d3ca5699545a393c26cab015d208432936a6b9d9f33");
	});

	it("killed-and-resumed: the interruption and the resume are in the lifecycle; two runs, interrupted then completed", () => {
		const t = trajectory(REAL, "killed-and-resumed");
		const kinds =
			t.layers.lifecycle.status === "reported" ? t.layers.lifecycle.entries.map((entry) => entry.kind) : [];
		expect(kinds).toEqual([
			"lifecycle.session-started",
			"lifecycle.run-started",
			"lifecycle.turn-started",
			"lifecycle.interrupted",
			"lifecycle.session-resumed",
			"lifecycle.run-started",
			"lifecycle.turn-started",
			"lifecycle.turn-completed",
			"lifecycle.run-completed",
			"lifecycle.detached",
		]);
		expect(t.layers.lifecycle).toMatchObject({
			entries: expect.arrayContaining([
				{
					kind: "lifecycle.interrupted",
					recognized: true,
					facts: expect.objectContaining({ cause: "observer-lost" }),
				},
				{
					kind: "lifecycle.session-resumed",
					recognized: true,
					facts: { runtime: "pi", previousEnd: "interrupted" },
				},
			]),
		});
		expect(t.layers.outcome).toMatchObject({
			entries: [
				{ run: 1, outcome: "interrupted", cause: { cause: "observer-lost" } },
				{ run: 2, outcome: "completed" },
			],
		});
		// Usage comes from the live stream only: the resumed run's one message, not again from the catch-up entries.
		expect(t.layers.usage).toMatchObject({
			entries: [
				{ run: 1, assistantMessages: 0, tokens: { status: "UNAVAILABLE" } },
				{ run: 2, assistantMessages: 1, tokens: { status: "reported", value: { input: 40, output: 231 } } },
			],
		});
		expect(t.layers.timing).toEqual({
			status: "reported",
			entries: [
				{
					run: 1,
					clock: "observer",
					wallMs: { status: "UNAVAILABLE", reason: "the run was interrupted; no end of it was observed" },
				},
				{ run: 2, clock: "observer", wallMs: { status: "reported", value: 3758 } },
			],
		});
	});

	it("killed-and-resumed: catch-up duplicates create no divergence", () => {
		const file = `${REAL}/killed-and-resumed.events.jsonl`;
		const events = lines(file);
		const session = piSession(events);
		const clean = projectPiTrajectoryV0(events, { store: file, session });
		// A reconnecting catch-up re-delivers durable entries the store already holds (same ids); replay twice over.
		const entries = events.filter((event) => event.kind === "session.entry-observed");
		const noisy = projectPiTrajectoryV0([...events, ...entries, ...events], { store: file, session });
		expect(noisy.source.duplicatesIgnored).toBe(entries.length + events.length);
		expect(canonicalEndoJsonV0(noisy.layers)).toBe(canonicalEndoJsonV0(clean.layers));
		const result = compare(clean, noisy);
		for (const layer of ["lifecycle", "tools", "outcome"] as const) expect(result.layers[layer].status).toBe("EXACT");
		expect(result.layers.usage).toMatchObject({ status: "DELTAS", totals: { tokens: { input: 0, output: 0 } } });
	});

	it("the 1.0.1 recordings predate pi-rpc-mapping.3: mapping and digest domain are UNAVAILABLE with the reason", () => {
		const t = trajectory(REAL, "completes");
		expect(t.environment.attachments[0]!.mapping).toEqual({
			status: "UNAVAILABLE",
			reason: "the attachment recorded no mapping version (pi-rpc-mapping.2 and earlier do not)",
		});
		expect(t.environment.attachments[0]!.digestKey).toEqual({
			status: "UNAVAILABLE",
			reason: "the attachment recorded no digest domain (recorded before keyed argument digests)",
		});
	});
});

describe("FAKE hostile recordings (fake Pi: proves the comparison sees each difference, not Pi behaviour)", () => {
	const baseline = () => trajectory(FAKE, "baseline");

	it("the committed files are the ones the manifest names", () => {
		const manifest = JSON.parse(readFileSync(join(REPO, FAKE, "manifest.json"), "utf8")) as {
			kind: string;
			cases: { name: string; eventsSha256: string }[];
		};
		expect(manifest.kind).toBe("fake-pi");
		for (const entry of manifest.cases) {
			const bytes = readFileSync(join(REPO, FAKE, `${entry.name}.events.jsonl`));
			expect(createHash("sha256").update(bytes).digest("hex")).toBe(entry.eventsSha256);
		}
	});

	it("baseline: two tool calls with keyed argument digests and results; mapping and digest domain recorded", () => {
		const t = baseline();
		expect(t.layers.tools).toEqual({
			status: "reported",
			entries: [
				{
					run: 1,
					turn: 1,
					name: { status: "reported", value: "read" },
					argsDigest: { status: "reported", value: piToolArgsDigestV0(KEY_A, { path: "a.txt" }) },
					result: { status: "reported", value: "ok" },
				},
				{
					run: 1,
					turn: 1,
					name: { status: "reported", value: "bash" },
					argsDigest: { status: "reported", value: piToolArgsDigestV0(KEY_A, { command: "ls" }) },
					result: { status: "reported", value: "ok" },
				},
			],
		});
		expect(t.environment.attachments[0]!.mapping).toEqual({ status: "reported", value: "pi-rpc-mapping.3" });
		expect(t.environment.attachments[0]!.digestKey).toEqual({
			status: "reported",
			value: { keyId: "fixture-public", domain: "fixture-public" },
		});
		expectSelfExact(t);
	});

	it("a second recording of the same behaviour is EXACT on every judged layer (ids, timestamps differ)", () => {
		const result = compare(baseline(), trajectory(FAKE, "baseline-again"));
		expect(result.a.eventsSha256).not.toBe(result.b.eventsSha256);
		for (const layer of ["lifecycle", "tools", "outcome"] as const) expect(result.layers[layer].status).toBe("EXACT");
		expect(result.flags).toEqual([]);
		expect(result.digest).toBe("7d55bddb98e8675e344030934be9b52a16f0d8884cd839192b8265d6d71fa6cb");
	});

	it("reordered tool calls diverge at the first call; lifecycle and outcome stay EXACT", () => {
		const result = compare(baseline(), trajectory(FAKE, "tools-reordered"));
		expect(result.layers.tools).toMatchObject({
			status: "DIVERGED",
			index: 0,
			commonPrefix: 0,
			a: { name: { value: "read" } },
			b: { name: { value: "bash" } },
		});
		expect(result.layers.lifecycle.status).toBe("EXACT");
		expect(result.layers.outcome.status).toBe("EXACT");
		expect(result.digest).toBe("deb78fa5e9e10b1434a4da06d19df534cfde7e3cb3ba593fdd282702002b19cc");
	});

	it("the same tool with different arguments diverges by argument digest", () => {
		const result = compare(baseline(), trajectory(FAKE, "tool-args-differ"));
		expect(result.layers.tools).toMatchObject({
			status: "DIVERGED",
			index: 0,
			a: { name: { value: "read" }, argsDigest: { value: piToolArgsDigestV0(KEY_A, { path: "a.txt" }) } },
			b: { name: { value: "read" }, argsDigest: { value: piToolArgsDigestV0(KEY_A, { path: "b.txt" }) } },
		});
		expect(result.digest).toBe("fbea43c734e4be267b309e9dbadd81104544b20eecb249ba960e7547ee4bf806");
	});

	it("a tool result status difference diverges at that call", () => {
		const result = compare(baseline(), trajectory(FAKE, "tool-errors"));
		expect(result.layers.tools).toMatchObject({
			status: "DIVERGED",
			index: 1,
			commonPrefix: 1,
			a: { result: { value: "ok" } },
			b: { result: { value: "error" } },
		});
		expect(result.digest).toBe("7f97c5cbe02ea2940d6c50fdd1b44782173378b614af9a396ccf53208851cc28");
	});

	it("one side missing usage: usage is UNAVAILABLE for that side, the judged layers are unaffected", () => {
		const result = compare(baseline(), trajectory(FAKE, "no-usage"));
		expect(result.layers.usage).toEqual({
			status: "UNAVAILABLE",
			a: null,
			b: "Pi reported no usage on any assistant message of this session",
		});
		for (const layer of ["lifecycle", "tools", "outcome"] as const) expect(result.layers[layer].status).toBe("EXACT");
		expect(result.digest).toBe("f6d6053856473b3bdf83f66763e8623e59add512f133722b0b34c776839e3c85");
	});

	it("an unknown runtime lifecycle record is a lifecycle divergence where it appeared", () => {
		const result = compare(baseline(), trajectory(FAKE, "unknown-lifecycle"));
		expect(result.layers.lifecycle).toMatchObject({
			status: "DIVERGED",
			index: 2,
			a: { kind: "lifecycle.turn-started" },
			b: { kind: "lifecycle.unrecognized-runtime-event", facts: { runtimeEvent: "agent_paused" } },
		});
		expect(result.layers.tools.status).toBe("EXACT");
		expect(result.digest).toBe("6bb1ef51db4f5eccf6f035fc15b1aa889b1d57afda31796f1c88d31beb0c76d7");
	});

	it("an undefined lifecycle.* kind is kept, unrecognized, by payload digest, and diverges", () => {
		// Hand-made, not fake-Pi output: a lifecycle kind from a future fold, inserted after run-started.
		const file = `${FAKE}/baseline.events.jsonl`;
		const events = lines(file);
		const at = events.findIndex((event) => event.kind === "lifecycle.run-started");
		const future: EndoEventV0 = {
			...events[at]!,
			id: "endo.event.pi-lifecycle.future-kind",
			kind: "lifecycle.run-paused",
			payload: { why: "future" },
		};
		const withFuture = [...events.slice(0, at + 1), future, ...events.slice(at + 1)];
		const t = projectPiTrajectoryV0(withFuture, { store: file, session: piSession(events) });
		expect(t.layers.lifecycle).toMatchObject({
			entries: expect.arrayContaining([
				{
					kind: "lifecycle.run-paused",
					recognized: false,
					facts: { payloadSha256: sha256HexV0(canonicalEndoJsonV0({ why: "future" })) },
				},
			]),
		});
		const result = compare(projectPiTrajectoryV0(events, { store: file, session: piSession(events) }), t);
		expect(result.layers.lifecycle).toMatchObject({
			status: "DIVERGED",
			index: 2,
			b: { kind: "lifecycle.run-paused" },
		});
	});

	it("different fingerprints are allowed but flagged; the verdicts are unchanged", () => {
		const result = compare(baseline(), trajectory(FAKE, "other-fingerprint"));
		expect(result.flags.map((flag) => flag.kind)).toEqual(["runtime-fingerprint-differs", "runtime-version-differs"]);
		expect(result.flags[1]).toEqual({ kind: "runtime-version-differs", a: ["1.0.0"], b: ["1.0.1"] });
		for (const layer of ["lifecycle", "tools", "outcome"] as const) expect(result.layers[layer].status).toBe("EXACT");
		expect(result.digest).toBe("93254b8adce0175c4563a6ce8c409ded2e5297246e979b2cf807e8a1890989b0");
	});

	it("real vs fake: model, mapping and fingerprint differences are all flagged, never mixed silently", () => {
		const result = compare(trajectory(REAL, "completes"), baseline());
		expect(result.flags.map((flag) => flag.kind)).toEqual([
			"runtime-fingerprint-differs",
			"runtime-version-differs",
			"mapping-differs",
			"digest-domain-differs",
			"configuration-differs",
			"configured-model-differs",
			"reported-model-differs",
		]);
	});

	it("an argument digest the recording did not capture leaves the tool layer UNAVAILABLE, not EXACT", () => {
		const file = `${FAKE}/baseline.events.jsonl`;
		const events = lines(file);
		const stripped = events.map((event) =>
			event.kind === "tool.started"
				? { ...event, payload: { ...(event.payload as Record<string, unknown>), argsDigest: undefined } }
				: event,
		);
		const old = projectPiTrajectoryV0(JSON.parse(JSON.stringify(stripped)), {
			store: file,
			session: piSession(events),
		});
		const result = compare(old, projectPiTrajectoryV0(events, { store: file, session: piSession(events) }));
		expect(result.layers.tools).toEqual({
			status: "UNAVAILABLE",
			a: null,
			b: null,
			unverified: [
				{ index: 0, reason: "no argument digest was recorded on one side" },
				{ index: 1, reason: "no argument digest was recorded on one side" },
			],
			lengths: { a: 2, b: 2 },
		});
	});

	it("digests from different digest domains are UNAVAILABLE (never DIVERGED), and the domain difference is flagged", () => {
		const other = trajectory(FAKE, "other-digest-domain");
		const keyB = FAKE_TRAJECTORY_DIGEST_KEYS.b;
		const result = compare(baseline(), other);
		const reason = `different digest domains (fixture-public and fixture-public-alt); to compare across machines, share one key: docs/trajectory.md#comparing-across-machines`;
		expect([KEY_A.keyId, keyB.keyId]).toEqual(["fixture-public", "fixture-public-alt"]);
		expect(result.layers.tools).toEqual({
			status: "UNAVAILABLE",
			a: null,
			b: null,
			unverified: [
				{ index: 0, reason },
				{ index: 1, reason },
			],
			lengths: { a: 2, b: 2 },
		});
		expect(result.flags).toEqual([{ kind: "digest-domain-differs", a: [KEY_A.keyId], b: [keyB.keyId] }]);
		for (const layer of ["lifecycle", "outcome"] as const) expect(result.layers[layer].status).toBe("EXACT");
		expect(result.digest).toBe("c1d1cfeb61c952e08946b82a51f8ede1dca68ceea3337953b64e674e1297618e");
	});

	it("a name or result difference still diverges across digest domains: only the digest is unverifiable", () => {
		const file = `${FAKE}/other-digest-domain.events.jsonl`;
		const events = lines(file);
		let first = true;
		const renamed = events.map((event) => {
			if (event.kind !== "tool.started" || !first) return event;
			first = false;
			return { ...event, payload: { ...(event.payload as Record<string, unknown>), toolName: "write" } };
		});
		const other = projectPiTrajectoryV0(renamed, { store: file, session: piSession(events) });
		expect(compare(baseline(), other).layers.tools).toMatchObject({ status: "DIVERGED", index: 0 });
	});
});

describe("keyed argument digests (the guessing risk they address)", () => {
	it("a plain sha256 of guessable arguments would be a confirmation oracle; the recording holds only HMACs", () => {
		const recorded = readFileSync(join(REPO, FAKE, "baseline.events.jsonl"), "utf8");
		// What plain hashing would have recorded, and what anyone could confirm by hashing the guess {"path":"a.txt"}:
		expect(recorded.includes(sha256HexV0(canonicalEndoJsonV0({ path: "a.txt" })))).toBe(false);
		// What is recorded instead: confirmable only by a holder of the domain key.
		expect(recorded.includes(KEY_A.digest({ path: "a.txt" }).value)).toBe(true);
		expect(recorded.includes(FAKE_TRAJECTORY_DIGEST_KEYS.b.digest({ path: "a.txt" }).value)).toBe(false);
	});

	it("are HMAC-SHA256 over canonical JSON: key order does not matter, values and keys do", () => {
		const digest = piToolArgsDigestV0(KEY_A, { path: "a.txt", limit: 2 })!;
		expect(digest).toMatchObject({ algorithm: "hmac-sha256", keyId: KEY_A.keyId });
		expect(piToolArgsDigestV0(KEY_A, { limit: 2, path: "a.txt" })).toEqual(digest);
		expect(piToolArgsDigestV0(KEY_A, { path: "a.txt", limit: 3 })!.value).not.toBe(digest.value);
		expect(piToolArgsDigestV0(FAKE_TRAJECTORY_DIGEST_KEYS.b, { path: "a.txt", limit: 2 })!.value).not.toBe(
			digest.value,
		);
		expect(digest.value).not.toBe(sha256HexV0(canonicalEndoJsonV0({ limit: 2, path: "a.txt" })));
		expect(piToolArgsDigestV0(KEY_A, undefined)).toBeUndefined();
		expect(piToolArgsDigestV0(null, { path: "a.txt" })).toBeUndefined();
	});

	it("the key id identifies the key without revealing it, and short keys are refused", () => {
		const bytes = Buffer.alloc(32, 7);
		expect(endoDigestKeyV0(bytes, "x").keyId).toBe(endoDigestKeyV0(Buffer.from(bytes), "y").keyId);
		expect(endoDigestKeyV0(bytes, "x").keyId).toMatch(/^endo\.digest-key\.[0-9a-f]{32}$/);
		expect(endoDigestKeyV0(bytes, "x").keyId).not.toContain(sha256HexV0(bytes).slice(0, 32));
		expect(endoDigestKeyV0(Buffer.alloc(32, 8), "x").keyId).not.toBe(endoDigestKeyV0(bytes, "x").keyId);
		expect(() => endoDigestKeyV0(Buffer.alloc(16), "x")).toThrow(/32 bytes/);
		expect(Object.keys(endoDigestKeyV0(bytes, "x"))).not.toContain("key");
	});
});

describe("the installation key file (storage/digest-key.ts): zero-config", () => {
	const scratch = () => {
		const dir = mkdtempSync(join(tmpdir(), "endo-digest-key-"));
		dirs.push(dir);
		return dir;
	};
	const warnings = () => {
		const seen: string[] = [];
		return { seen, warn: (message: string) => seen.push(message) };
	};

	it("lives in Endophasia's data directory: ENDO_DIGEST_KEY_FILE, then XDG_DATA_HOME, then HOME; never in a store", () => {
		expect(endoDigestKeyPathV0({ ENDO_DIGEST_KEY_FILE: "/k", XDG_DATA_HOME: "/x", HOME: "/h" })).toBe("/k");
		expect(endoDigestKeyPathV0({ XDG_DATA_HOME: "/x", HOME: "/h" })).toBe("/x/endophasia/digest-key");
		expect(endoDigestKeyPathV0({ HOME: "/h" })).toBe("/h/.local/share/endophasia/digest-key");
		expect(() => endoDigestKeyPathV0({})).toThrow(/no digest key location/);
		// The test run itself never touches the operator's installation key (vitest.config.ts).
		expect(process.env.ENDO_DIGEST_KEY_FILE).toMatch(/endo-vitest-digest-key-/);
	});

	it("is generated on first use, owner-only, without a prompt or warning, and reloads to the same key", () => {
		const path = join(scratch(), "data", "endophasia", "digest-key");
		const { seen, warn } = warnings();
		const created = endoDigestKeyFromEnvironmentV0({ XDG_DATA_HOME: join(path, "..", "..") }, warn);
		expect(statSync(path).mode & 0o777).toBe(0o600);
		expect(statSync(join(path, "..")).mode & 0o777).toBe(0o700);
		expect(created).toMatchObject({ domain: "installation", public: false });
		expect(created.keyId).toMatch(/^endo\.digest-key\.[0-9a-f]{32}$/);
		const again = loadOrCreateEndoDigestKeyV0(path, warn);
		expect(again.keyId).toBe(created.keyId);
		expect(again.digest({ a: 1 })).toEqual(created.digest({ a: 1 }));
		expect(seen).toEqual([]);
	});

	it("wider than owner-only permissions: warns clearly and continues, and never chmods the file", () => {
		const path = join(scratch(), "digest-key");
		const created = loadOrCreateEndoDigestKeyV0(path);
		chmodSync(path, 0o644);
		const { seen, warn } = warnings();
		expect(loadOrCreateEndoDigestKeyV0(path, warn).keyId).toBe(created.keyId);
		expect(seen).toEqual([expect.stringMatching(/has mode 0644, wider than owner-only.*chmod 600/)]);
		expect(statSync(path).mode & 0o777).toBe(0o644);
		// Owner-only read is owner-only: no warning.
		chmodSync(path, 0o400);
		const quiet = warnings();
		readEndoDigestKeyV0(path, quiet.warn);
		expect(quiet.seen).toEqual([]);
	});

	it("refuses a malformed file, and a public fixture key as the installation key", () => {
		const bad = join(scratch(), "digest-key");
		writeFileSync(bad, '{"schemaVersion":"endo.digest-key.v0","domain":"x","key":"abcd"}', { mode: 0o600 });
		expect(() => readEndoDigestKeyV0(bad)).toThrow(/not an endo.digest-key.v0 file/);
		const copy = join(scratch(), "digest-key");
		writeFileSync(copy, readFileSync(FIXTURE_KEY_FILE), { mode: 0o600 });
		expect(() => readEndoDigestKeyV0(copy)).toThrow(
			/public fixture key \(fixture-public\).*never used as the installation key/,
		);
	});

	it("`endo digest-key id` prints the id, domain and path, and never creates a key", () => {
		const dir = scratch();
		const path = join(dir, "digest-key");
		expect(() => digestKeyCommand(["id"], { ENDO_DIGEST_KEY_FILE: path })).toThrow(/no digest key at/);
		expect(() => statSync(path)).toThrow();
		const key = loadOrCreateEndoDigestKeyV0(path);
		let out = "";
		const spy = vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
			out += String(chunk);
			return true;
		});
		try {
			digestKeyCommand(["id"], { ENDO_DIGEST_KEY_FILE: path });
		} finally {
			spy.mockRestore();
		}
		expect(JSON.parse(out)).toEqual({ keyId: key.keyId, domain: "installation", path });
		expect(out).not.toContain(JSON.parse(readFileSync(path, "utf8")).key);
		expect(() => digestKeyCommand([], { ENDO_DIGEST_KEY_FILE: path })).toThrow(/usage/);
	});
});

describe("the public fixture key (research/fixture-keys/)", () => {
	it("is named fixture-public, marked public, and pinned to its bytes", () => {
		const key = loadEndoFixtureDigestKeyV0(FIXTURE_KEY_FILE);
		expect(key).toMatchObject({ keyId: "fixture-public", domain: "fixture-public", public: true });
		expect(key.fingerprint).toBe(ENDO_FIXTURE_DIGEST_KEYS_V0["fixture-public"]);
		const file = JSON.parse(readFileSync(FIXTURE_KEY_FILE, "utf8"));
		const forged = join(mkdtempSync(join(tmpdir(), "endo-digest-key-")), "fixture-public.json");
		dirs.push(join(forged, ".."));
		writeFileSync(forged, JSON.stringify({ ...file, key: "ab".repeat(32) }));
		expect(() => loadEndoFixtureDigestKeyV0(forged)).toThrow(/does not hold the pinned fixture-public key/);
		writeFileSync(forged, JSON.stringify({ ...file, public: false }));
		expect(() => loadEndoFixtureDigestKeyV0(forged)).toThrow(/not a committed public fixture key/);
		expect(readFileSync(join(FIXTURE_KEY_FILE, "..", "README.md"), "utf8")).toMatch(/offer no secrecy/);
	});

	it("recording a normal session under fixture-public is refused", () => {
		const pi = new PiAttachmentV0({
			root: mkdtempSync(join(tmpdir(), "endo-digest-key-")),
			digestKey: loadEndoFixtureDigestKeyV0(FIXTURE_KEY_FILE),
		});
		expect(() => pi.digestKey()).toThrow(
			/refusing to record a normal session under the public fixture key fixture-public/,
		);
	});

	it("recording a fixture under an installation key is refused, and so is a fixture with no key", () => {
		const root = mkdtempSync(join(tmpdir(), "endo-digest-key-"));
		dirs.push(root);
		const installation = loadOrCreateEndoDigestKeyV0(join(root, "digest-key"));
		const pi = new PiAttachmentV0({ root, digestKey: installation, digestDomain: "fixture" });
		expect(() => pi.digestKey()).toThrow(
			/refusing to record a fixture under the installation key endo\.digest-key\./,
		);
		expect(() => new PiAttachmentV0({ root, digestDomain: "fixture" }).digestKey()).toThrow(
			/a fixture recording needs a committed public fixture key/,
		);
		// The two allowed pairings.
		expect(new PiAttachmentV0({ root, digestKey: installation }).digestKey().keyId).toBe(installation.keyId);
		expect(
			new PiAttachmentV0({
				root,
				digestKey: loadEndoFixtureDigestKeyV0(FIXTURE_KEY_FILE),
				digestDomain: "fixture",
			}).digestKey().keyId,
		).toBe("fixture-public");
	});

	it("the fixture recorder records under fixture-public, never the installation key", () => {
		expect(PI_LIFECYCLE_FIXTURE_DIGEST_KEY).toBe(FIXTURE_KEY_FILE);
	});
});

describe("endo trajectory show / diff", () => {
	function capture(run: () => void): string {
		let out = "";
		const spy = vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
			out += String(chunk);
			return true;
		});
		try {
			run();
		} finally {
			spy.mockRestore();
		}
		return out;
	}

	function store(name: string): { root: string; session: string } {
		const events = lines(`${REAL}/${name}.events.jsonl`);
		const root = mkdtempSync(join(tmpdir(), "endo-trajectory-cli-"));
		dirs.push(root);
		const created = createEndoDurableEventStoreV0(root);
		for (const event of events) created.ingest(event);
		created.close();
		return { root, session: piSession(events) };
	}

	it("print one canonical-JSON document each and change nothing on disk", () => {
		const a = store("completes");
		const b = store("stop-mid-turn");
		const log = join(a.root, "events", "events.log");
		const before = readFileSync(log);
		const shown = capture(() => trajectoryShowCommand([a.root, a.session]));
		expect(canonicalEndoJsonV0(JSON.parse(shown))).toBe(shown);
		expect(validateEndoTrajectoryV0(JSON.parse(shown), endoRecordDigestV0)).not.toBeNull();
		const diff = capture(() => trajectoryDiffCommand([a.root, a.session, b.root, `endo.session.pi.${b.session}`]));
		expect(canonicalEndoJsonV0(JSON.parse(diff))).toBe(diff);
		expect(JSON.parse(diff).layers.lifecycle.index).toBe(3);
		expect(readFileSync(log).equals(before)).toBe(true);
	});

	it("name the recorded sessions when the requested one is not there", () => {
		const a = store("completes");
		expect(() => trajectoryShowCommand([a.root, "no-such-session"])).toThrow(
			new RegExp(`recorded sessions: endo\\.session\\.pi\\.${a.session}`),
		);
		expect(() => trajectoryShowCommand([a.root])).toThrow(/usage/);
		expect(() => trajectoryShowCommand([a.root, a.session, "--bogus", "x"])).toThrow(/unknown flag/);
	});
});

describe("REAL Pi 1.0.1 completes-repeat (a preliminary observation, not a variance result)", () => {
	const REPEAT = "research/pi-conformance/1.0.1/completes-repeat";

	it("the committed files are the ones each provenance names, recorded under pi-rpc-mapping.3", () => {
		for (const run of ["run-1", "run-2"]) {
			const provenance = JSON.parse(readFileSync(join(REPO, REPEAT, run, "provenance.json"), "utf8"));
			expect(provenance).toMatchObject({ kind: "real", endophasia: { mapping: "pi-rpc-mapping.3" } });
			expect(provenance.sessions.map((session: { name: string }) => session.name)).toEqual(["completes"]);
			const bytes = readFileSync(join(REPO, REPEAT, run, "completes.events.jsonl"));
			expect(createHash("sha256").update(bytes).digest("hex")).toBe(provenance.sessions[0].eventsSha256);
		}
	});

	it("run-1 vs run-2: EXACT on every judged layer, no flags, usage reported as deltas only", () => {
		const result = compare(trajectory(`${REPEAT}/run-1`, "completes"), trajectory(`${REPEAT}/run-2`, "completes"));
		expect(result.flags).toEqual([]);
		for (const layer of ["lifecycle", "tools", "outcome"] as const) expect(result.layers[layer].status).toBe("EXACT");
		expect(result.layers.usage).toMatchObject({
			status: "DELTAS",
			totals: { tokens: { input: 0, output: 6, cacheRead: 0 } },
		});
		expect(result.layers.timing).toMatchObject({ status: "DELTAS", clock: "observer", totals: { wallMs: 5 } });
		expect(result.digest).toBe("674191e7e1d5b41c734a2225df079592cc119cdd2c15fe124edd6ebaaa2243ff");
	});

	it.each(["run-1", "run-2"])(
		"the committed lifecycle completes vs %s: EXACT, mapping and digest domain flagged",
		(run) => {
			const result = compare(trajectory(REAL, "completes"), trajectory(`${REPEAT}/${run}`, "completes"));
			expect(result.flags).toEqual([
				{ kind: "mapping-differs", a: [null], b: ["pi-rpc-mapping.3"] },
				{ kind: "digest-domain-differs", a: [null], b: ["endo.digest-key.02afbe04de932c3972f4e457effbdab8"] },
			]);
			for (const layer of ["lifecycle", "tools", "outcome"] as const)
				expect(result.layers[layer].status).toBe("EXACT");
			expect(result.layers.usage).toMatchObject({ status: "DELTAS", totals: { tokens: { cacheRead: 1476 } } });
		},
	);
});

